use mcrf_bs_routing_policy::{inspect::{self,Inspection},dns_wire};
fn known(p:&'static str)->Inspection{Inspection::Known{protocol:p,domain:None}}
#[test]fn queries_never_become_destination_domains(){let bytes=dns_wire::query(42,"private.invalid",1).unwrap();assert_eq!(inspect::datagram(&bytes,"dns"),known("dns"));assert_eq!(inspect::datagram(&bytes,"tls"),Inspection::Unknown);}
#[test]fn warp_reserved_bytes_and_packet_lengths(){for (kind,size) in [(1,148),(2,92),(3,64),(4,32),(4,48)]{let mut b=vec![0;size];b[..4].copy_from_slice(&[kind,0x12,0x34,0x56]);assert_eq!(inspect::datagram(&b,"wireguard"),known("wireguard"));b.pop();assert_eq!(inspect::datagram(&b,"wireguard"),Inspection::Unknown)}}
#[test]fn bounded_inputs_and_unknown_selectors(){for n in 0..20{let b=vec![0;n];for sniffer in inspect::UDP_SNIFFERS{let _=inspect::datagram(&b,sniffer);}}assert_eq!(inspect::datagram(&vec![1;65536],"wireguard"),Inspection::Unknown);assert!(!inspect::supports("unknown"));}
#[test]fn dtls_stun_and_ntp_require_headers(){let mut d=vec![0;13];d[..3].copy_from_slice(&[22,0xfe,0xfd]);assert_eq!(inspect::datagram(&d,"dtls"),known("dtls"));let mut s=vec![0;20];s[4..8].copy_from_slice(&[0x21,0x12,0xa4,0x42]);assert_eq!(inspect::datagram(&s,"stun"),known("stun"));s[3]=1;assert_eq!(inspect::datagram(&s,"stun"),Inspection::Unknown);let mut n=vec![0;48];n[0]=(4<<3)|3;assert_eq!(inspect::datagram(&n,"ntp"),known("ntp"));n[0]=(4<<3)|4;assert_eq!(inspect::datagram(&n,"ntp"),Inspection::Unknown);}
